\section{Three endpoint estimates}
An eligible pair means differentiable $x,z$ satisfying \eqref{C:eq:eligible}, with $s=z-x$, $g=\nabla F(x)$, $y=\nabla F(z)-g$, and $t=y^Ts$. For each fixed valid pair $(c_1,c_2)$, the following three estimates hold for the same objective-constructed field $w$. There are an open set $U\supset C$, a compact buffer $Q\supset\overline U$, and positive uniform distance and visibility constants such that every sufficiently close eligible pair $x,z\in U$ is covered, with its entire segment in $Q$. On $Q$, every subgradient at a given point has the same strictly positive pairing with $w$, bounded uniformly away from zero. All constants and neighborhoods are chosen before the endpoint pair; none depends on a BFGS matrix or on an assumed trajectory limit.

\begin{lemma}[Uniform transversality]\label{C:lem:trans}
There is $\kappa>0$ such that
\[
 |\det(s,w(x+\theta s))|\ge\kappa\norm{s}
 \quad(0\le\theta\le1)
\]
for all sufficiently close eligible pairs.
\end{lemma}
\begin{proof}
Otherwise take pairs coalescing to $p$ in the compact neighborhood, unit steps $s/\norm{s}\to e$, and segment points where the normalized determinant tends to zero. Continuity of $w$ implies $e$ is parallel to $w(p)$. Subgradient limits $a,b\in\partial F(p)$ have the same strictly positive inner product with $w(p)$: this is automatic at a smooth point and follows from \eqref{C:eq:vel} at a corner. Descent selects $e=-w(p)/\norm{w(p)}$, so $d/\norm{s}\to-a^Te>0$. But
\[
 t/\norm{s}\to(b-a)^Te=0,
\]
contradicting $t\ge(1-c_2)d$. Compactness makes the bound uniform, including all segment points.
\end{proof}

\begin{lemma}[Transport is charged to objective decrease]\label{C:lem:transport}
For the same pairs, there are scalars $\lambda>0,\beta$ satisfying
\begin{equation}\label{C:eq:transport}
 w(z)=\lambda w(x)+\beta s,\qquad
 |\log\lambda|\le C d.
\end{equation}
In particular $\lambda^2\le1+C'd$ for sufficiently small $d$.
\end{lemma}
\begin{proof}
Let $q(\theta)=x+\theta s$, $\varphi(\theta)=F(q(\theta))$, and $D(\theta)=\det(s,w(q(\theta)))$. Transversality makes the continuous function $D$ nonzero throughout $[0,1]$, hence of constant sign.

On a smooth part of the segment, use \eqref{C:eq:triangular}. The ordered orthonormal basis $(T,n)$ has determinant $-1$. Consequently, with $s=s_TT+s_n n$, the correctly oriented identity is
\[
 \det(s,Dw\,s)=s_n[(a-e)s_T+b s_n].
\]
Its absolute value, the uniform derivative bound, transversality and the positive lower bound on $\norm{\nabla F}$ give the required determinant-derivative estimate. In a corner neighborhood, $w\circ q=v_j\circ\varphi$. The convex function $\varphi$ has an actual right derivative at every $\theta<1$; the ordinary one-sided chain rule therefore handles corner points as well as smooth points. We obtain, for one $C\ge0$,
\[
 \left|\frac{D'_+(\theta)}{D(\theta)}\right|
 \le C|\varphi'_+(\theta)|,\qquad 0\le\theta<1.
\]
No finite bound on intersections with a switching curve is used.

Set $h(\theta)=\log|D(\theta)|$. Convexity and $\varphi'(0)=-d$ imply $\varphi'_+(\theta)\ge-d$, and hence
\begin{equation}\label{C:eq:variation}
 |h'_+(\theta)|\le C|\varphi'_+(\theta)|
 \le C(\varphi'_+(\theta)+2d).
\end{equation}
Apply the one-sided derivative comparison theorem to the continuous observable $h-h(0)$ and the barrier
\[
 B(\theta)=C[\varphi(\theta)-\varphi(0)+2d\theta].
\]
The initial value is zero and the right-derivative norm is bounded by $B'_+$. Thus $|h(1)-h(0)|\le B(1)\le2Cd$, since $\varphi(1)\le\varphi(0)$. Because $D(1)/D(0)>0$, this is $|\log(D(1)/D(0))|\le2Cd$. Finally $s,w(x)$ form a basis, and solving in that basis gives $w(z)=\lambda w(x)+\beta s$ with $\lambda=D(1)/D(0)>0$. Absorb the factor two into the stated constant. This proves the claim.
\end{proof}

\begin{lemma}[Bounded secant correction]\label{C:lem:secant}
There is a uniform $C_0<\infty$ such that
\[
 \frac{(y^Tw(z))^2}{t}\le C_0
\]
for all sufficiently close eligible pairs in the same neighborhood.
\end{lemma}
\begin{proof}
Use a finite buffered chart cover. For close pairs in a common smooth chart, or with the same active branch in a two-branch chart, the local convex gradient-increment estimate gives $\norm{y}^2\le L t$ for a uniform constant $L$. One proof subtracts a tangent plane, applies the descent estimate to a short step opposite the gradient difference within the larger convex chart, and combines the resulting one-sided inequalities. Compact buffering supplies a single constant; no positive lower Hessian bound is required. Bounded $w$ proves the claim.

For different active branches $i,j$ in a two-branch chart, the segment has a tie point $p$. At that point the jump is orthogonal to $w(p)$. The branch gradients and $w$ are Lipschitz, so
\begin{equation}\label{C:eq:numerator}
 |y^Tw(z)|\le C_1\norm{s}.
\end{equation}
For the denominator put $a=\nabla f_i(x)$, $b=\nabla f_j(x)$, and $r=\nabla f_j(z)-\nabla f_j(x)$, with $\norm{r}\le L\norm{s}$. Then
\[
 a^Ts=-d,\qquad b^Ts=t-d-r^Ts.
\]
The two gradient rows are uniformly independent on the chart. Thus
\[
 \norm{s}\le A(2d+t+L\norm{s}^2)
 \le A\left(1+\frac{2}{1-c_2}\right)t+AL\norm{s}^2.
\]
For small $s$, absorb the final term to obtain $t\ge c_0\norm{s}$. Combining with \eqref{C:eq:numerator} bounds the correction by a constant times $\norm{s}$, hence uniformly. This is a crossing-specific linear curvature estimate, not a uniform positive Hessian assumption.
\end{proof}


